css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .5); display: flex; align-items: center; justify-content: space-between; }
.loader span { position: relative; width: calc(var(--loader-size) * .07); height: 100%; }
.loader span::before, .loader span::after { content: ''; position: absolute; left: 0; width: 100%; aspect-ratio: 1; border-radius: 50%; }
.loader span::before { background: var(--accent); animation: helix-a calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader span::after { background: var(--accent-2); animation: helix-b calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader span:nth-child(1) { animation-delay: 0s; } .loader span:nth-child(1)::before, .loader span:nth-child(1)::after { animation-delay: 0s; }
.loader span:nth-child(2)::before, .loader span:nth-child(2)::after { animation-delay: calc(var(--loader-speed) * .18); }
.loader span:nth-child(3)::before, .loader span:nth-child(3)::after { animation-delay: calc(var(--loader-speed) * .36); }
.loader span:nth-child(4)::before, .loader span:nth-child(4)::after { animation-delay: calc(var(--loader-speed) * .54); }
.loader span:nth-child(5)::before, .loader span:nth-child(5)::after { animation-delay: calc(var(--loader-speed) * .72); }
.loader span:nth-child(6)::before, .loader span:nth-child(6)::after { animation-delay: calc(var(--loader-speed) * .9); }
.loader span:nth-child(7)::before, .loader span:nth-child(7)::after { animation-delay: calc(var(--loader-speed) * 1.08); }
.loader span:nth-child(8)::before, .loader span:nth-child(8)::after { animation-delay: calc(var(--loader-speed) * 1.26); }
@keyframes helix-a { 0%, 100% { top: 0; transform: scale(.55); z-index: 1; } 50% { top: calc(100% - var(--loader-size) * .07); transform: scale(1); z-index: 3; } }
@keyframes helix-b { 0%, 100% { top: calc(100% - var(--loader-size) * .07); transform: scale(1); z-index: 3; } 50% { top: 0; transform: scale(.55); z-index: 1; } }
